function validateApplications(raw) {
    const s = raw;
    if (!s || typeof s.updatedAt !== 'string' || !/(Z|[+-]\d{2}:\d{2})$/.test(s.updatedAt) || !Number.isFinite(Date.parse(s.updatedAt)) || !Array.isArray(s.items) || s.items.length > 100)
        throw Error('Ongeldig sollicitatieoverzicht.');
    const ids = new Set();
    for (const a of s.items) {
        if (!a || ['id', 'company', 'role', 'status', 'nextAction'].some(k => typeof a[k] !== 'string' || !a[k].trim() || a[k].length > 2000) || ids.has(a.id) || !['waiting', 'action', 'interview', 'closed'].includes(a.stage))
            throw Error('Ongeldig sollicitatietraject.');
        ids.add(a.id);
        if (a.color !== undefined && !['green', 'orange', 'red'].includes(a.color))
            throw Error('Ongeldig statusbolletje.');
        if (a.note !== undefined && (typeof a.note !== 'string' || a.note.length > 4000))
            throw Error('Ongeldige sollicitatienotitie.');
        if (a.acknowledgedUpdateId !== undefined && (typeof a.acknowledgedUpdateId !== 'string' || !a.acknowledgedUpdateId.trim()))
            throw Error('Ongeldige updatebevestiging.');
        if (a.actionDate !== undefined && (!/^\d{4}-\d{2}-\d{2}$/.test(a.actionDate) || !Number.isFinite(Date.parse(a.actionDate + 'T00:00:00Z')) || new Date(a.actionDate + 'T00:00:00Z').toISOString().slice(0, 10) !== a.actionDate))
            throw Error('Ongeldige actiedatum.');
        if (a.appointment !== undefined && (!/(Z|[+-]\d{2}:\d{2})$/.test(a.appointment) || !Number.isFinite(Date.parse(a.appointment))))
            throw Error('Ongeldig gesprekstijdstip.');
        if (a.url !== undefined && !/^https:\/\//.test(a.url))
            throw Error('Ongeldige sollicitatielink.');
    }
    return s;
}
